    59  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    60  {
    61      otMessage *message = NULL;
    62      otError error = OT_ERROR_NONE;
    63      bool isSecure;
    64
    65      VerifyOrExit(size > 0);
    66
    67      isSecure = (data[0] & 0x1) != 0;
    68
    69      message = otIp6NewMessage(sInstance, isSecure);
    70      VerifyOrExit(message != NULL, error = OT_ERROR_NO_BUFS);
    71
    72      error = otMessageAppend(message, data + 1, static_cast<uint16_t>(size - 1));
    73      SuccessOrExit(error);
    74
    75      error = otIp6Send(sInstance, message);
    76      SuccessOrExit(error);
    77
    78  exit:
    79      return 0;
    80  }
